input.command:
$maxAttempts = 60
$attempt = 0
$started = $false

while ($attempt -lt $maxAttempts -and -not $started) {
    try {
        $response = Invoke-WebRequest -Uri "https://localhost:44317" -SkipCertificateCheck -UseBasicParsing -TimeoutSec 5
        if ($response.StatusCode -eq 200) {
            $started = $true
            Write-Host "✓ Umbraco is running"
            break
        }
    } catch {
        $attempt++
        if ($attempt % 10 -eq 0) {
            Write-Host "Waiting for Umbraco... (attempt $attempt/$maxAttempts)"
        }
        Start-Sleep -Seconds 1
    }
}

if (-not $started) {
    Write-Host "✗ Umbraco did not start within 60 seconds"
} else {
    Write-Host "Umbraco ready after $attempt attempts"
}

