input.command:
Start-Sleep -Seconds 30
$maxAttempts = 60
$attempt = 0
$started = $false

while ($attempt -lt $maxAttempts -and -not $started) {
    try {
        $response = Invoke-WebRequest -Uri "https://localhost:44317" -SkipCertificateCheck -UseBasicParsing -TimeoutSec 5 -ErrorAction Stop
        if ($response.StatusCode -eq 200) {
            $started = $true
            Write-Host "✓ Umbraco is responding"
            break
        }
    } catch {
        $attempt++
        if ($attempt % 10 -eq 0) {
            Write-Host "Waiting... attempt $attempt"
        }
        Start-Sleep -Seconds 1
    }
}

if ($started) {
    Write-Host "Umbraco ready"
} else {
    Write-Host "Umbraco not responding after $attempt attempts"
}

