$blogFrontPageTemplate = @'
@using Umbraco.Cms.Web.Common.Views
@using Umbraco.Cms.Core.Models.PublishedContent
@inherits UmbracoViewPage
@{
    Layout = null;
}
<!DOCTYPE html>
<html>
<head>
    <title>@Model.Value("title")</title>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body>
    <div class="container mx-auto p-8">
        <h1 class="text-4xl font-bold mb-8">@Model.Value("title")</h1>

        <div class="grid gap-8">
            @{
                var children = Model.Children();
                foreach (var post in children)
                {
                    var title = post.Value("title");
                    var excerpt = post.Value("excerpt");
                    var date = post.Value("publishDate");
                    var image = post.Value<IPublishedContent>("featuredImage");
                    <article class="border rounded-lg overflow-hidden shadow-sm">
                        @if (image != null)
                        {
                            <div class="aspect-video overflow-hidden bg-gray-100">
                                <img src="@image.GetCropUrl(width: 400, height: 300)" alt="@title" class="w-full h-full object-cover" />
                            </div>
                        }
                        <div class="p-6">
                            <h2 class="text-2xl font-bold mb-2">
                                <a href="@post.Url()" class="hover:underline">@title</a>
                            </h2>
                            @if (date != null)
                            {
                                <time class="text-gray-500 text-sm mb-4 block">@((DateTime)date).ToString("MMMM d, yyyy")</time>
                            }
                            <div class="prose max-w-none">
                                @Html.Raw(excerpt?.ToString() ?? "")
                            </div>
                            <a href="@post.Url()" class="inline-block mt-4 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">Read More</a>
                        </div>
                    </article>
                }
            }
        </div>
    </div>
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>
'@

$blogFrontPageTemplate | Out-File -FilePath "C:\code\benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\Views\blogFrontPage.cshtml" -Encoding UTF8 -Force
Write-Host "Models and templates updated"

