$blogPostTemplate = @'
@using Umbraco.Cms.Web.Common.Views
@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Cms.Core.Models.PublishedContent
@inherits UmbracoViewPage
@{
    Layout = null;
}
<!DOCTYPE html>
<html>
<head>
    <title>@Model.Value("title")</title>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body>
    <div class="container mx-auto p-8 max-w-3xl">
        <article>
            <header class="mb-8">
                <h1 class="text-4xl font-bold mb-4">@Model.Value("title")</h1>
                @{
                    var date = Model.Value("publishDate");
                    if (date != null)
                    {
                        <time class="text-gray-500">@((DateTime)date).ToString("MMMM d, yyyy")</time>
                    }
                }
            </header>

            @{
                var featuredImage = Model.Value<IPublishedContent>("featuredImage");
                if (featuredImage != null)
                {
                    <figure class="mb-8 aspect-video overflow-hidden rounded-lg bg-gray-100">
                        <img src="@featuredImage.GetCropUrl(width: 800, height: 450)" alt="@Model.Value("title")" class="w-full h-full object-cover" />
                    </figure>
                }
            }

            <div class="prose max-w-none mb-8">
                @Html.Raw(Model.Value("excerpt")?.ToString() ?? "")
            </div>

            @await Html.GetBlockGridHtmlAsync(Model, "body")
        </article>

        <nav class="mt-12 pt-8 border-t">
            @{
                var parent = Model.Parent;
                if (parent != null)
                {
                    var parentUrl = parent.Url();
                    <a href="@parentUrl" class="inline-block px-4 py-2 bg-gray-200 rounded hover:bg-gray-300">Back to Blog</a>
                }
            }
        </nav>
    </div>
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>
'@

