$ProgressPreference = 'SilentlyContinue'
Start-Sleep -Seconds 10

$urls = @(
    "https://localhost:44317/",
    "https://localhost:44317/blog/why-mcp-is-awesome",
    "https://localhost:44317/blog/mcp-use-cases"
)

foreach ($url in $urls) {
    Write-Host "`n--- Testing $url ---"
    try {
        $response = Invoke-WebRequest -Uri $url -SkipCertificateCheck -UseBasicParsing -TimeoutSec 5
        Write-Host "Status: $($response.StatusCode)"
        Write-Host "Content length: $($response.Content.Length) bytes"

        # Check for errors in content
        if ($response.Content -like "*Could not render component*") {
            Write-Host "⚠ Found 'Could not render component' error"
        } elseif ($response.Content -like "*error*" -or $response.Content -like "*Error*") {
            Write-Host "⚠ Found error in content"
        } else {
            Write-Host "✓ No obvious errors"
        }

        # Show title if it's HTML
        if ($response.Content -match "<title>([^<]+)</title>") {
            Write-Host "Title: $($matches[1])"
        }
    } catch {
        Write-Host "✗ Error: $($_.Exception.Message)"
    }
}

